/**
 * CATÁLOGO TÉCNICO ULTRA EXPANDIDO 2026 — Tattoo CRM
 *
 * Estrutura:
 * Marca / linha | SKU/modelo | Formato | Pontas | Diâmetro | Taper |
 * Embalagem | Aplicação | Evidência | Ação
 *
 * REGRAS:
 * 1) Catálogo global de referência. Estoque, preço, lote, validade e fornecedor pertencem ao tenant/estúdio/artista.
 * 2) Nunca vincular fornecedor automaticamente. Só mostrar fornecedor compatível quando houver vínculo auditável.
 * 3) Produtos com evidenceStatus === "bloqueado" ou anvisaStatus === "bloqueado" não podem ser adotados no estoque.
 * 4) Para tintas/pigmentos, "fabricante" confirma existência comercial; não confirma sozinho regularização sanitária no Brasil.
 * 5) Itens "pendente" exigem confirmação de marca/SKU/embalagem/registro antes de compra/uso.
 * 6) Alguns fabricantes usam um SKU-base com seletor de configuração. Nesses casos o CRM usa SKU interno normalizado e preserva a URL oficial.
 *
 * Pesquisa técnica ampliada em 2026-09-07.
 */

export type EvidenceStatus = "fabricante" | "fornecedor" | "pendente" | "bloqueado";
export type AnvisaStatus = "nao_aplicavel" | "regularizado" | "pendente" | "bloqueado";

export type TechnicalCatalogSeedItem = {
  brandName: string;
  lineName: string;
  name: string;
  sku: string | null;
  category: string;
  format: string | null;
  needleCount: number | null;
  needleDiameter: number | null;
  taper: string | null;
  packageQuantity: number | null;
  packageUnit: string | null;
  baseUnit: string;
  purchaseUnit: string;
  unitsPerPackage: number;
  volumeMl: number | null;
  colorName: string | null;
  anvisaStatus: AnvisaStatus;
  requiresLotControl: 0 | 1;
  application: string | null;
  evidenceStatus: EvidenceStatus;
  sourceUrl: string | null;
  notes: string | null;
};

