export function canAddCatalogItemToOperationalStock(item: TechnicalCatalogSeedItem) {
  return item.evidenceStatus !== "bloqueado" && item.anvisaStatus !== "bloqueado";
}

export function catalogSearchText(item: TechnicalCatalogSeedItem) {
  return [
    item.brandName,
    item.lineName,
    item.name,
    item.sku,
    item.category,
    item.format,
    item.needleCount,
    item.needleDiameter,
    item.taper,
    item.packageUnit,
    item.application,
  ]
    .filter((value) => value !== null && value !== undefined)
    .join(" ")
    .toLowerCase();
}

export function filterTechnicalCatalog(
  rows: TechnicalCatalogSeedItem[],
  filters: {
    query?: string;
    category?: string;
    brand?: string;
    line?: string;
    format?: string;
  },
) {
  const q = filters.query?.trim().toLowerCase();
  return rows.filter((item) => {
    if (filters.category && filters.category !== "all" && item.category !== filters.category) return false;
    if (filters.brand && filters.brand !== "all" && item.brandName !== filters.brand) return false;
    if (filters.line && filters.line !== "all" && item.lineName !== filters.line) return false;
    if (filters.format && filters.format !== "all" && item.format !== filters.format) return false;
    if (q && !catalogSearchText(item).includes(q)) return false;
    return true;
  });
}

